function p(r,n,h,c){const g=r.findIndex(i=>h(i,n));if(g<0)return{changes:[...r,n],id:n.id};const o=r.slice(),t=o[g];return o[g]={...c(t,n),id:t.id},{changes:o,id:t.id}}function f(r,n,h,c,g){const o=new Map(h.map(e=>[e.id,e])),t=new Map(n.map(e=>[e.id,e])),i=[];let d=0;for(const e of n){const a=o.get(e.id);a?.ok?d++:i.push({...e,error:a?.error??"commit failed"})}const s=[];for(const e of r){const a=t.get(e.id);if(!a){s.push(e);continue}const C=o.get(e.id);c(e,a)?C?.ok||s.push({...e,error:C?.error??"commit failed"}):s.push(C?.ok?g(e,a):e)}return{changes:s,applied:d,failed:i}}export{f as reconcileWorkspaceChanges,p as stageWorkspaceChange};
